@Service @Profile("db")
public final class JdbcExchangeDispatches implements ExchangeDispatches {
 public static final String TYPE="EXCHANGE_RESHIP.v1";
 private final NamedParameterJdbcTemplate jdbc;private final ExchangeApplications applications;private final PhysicalOrders physical;private final ExchangeReservations reservations;private final PhysicalStocks stocks;private final ExchangeShipments shipments;private final ExchangeOffers offers;private final JdbcExchanges exchanges;private final Jobs jobs;private final JobLeases leases;private final Outbox outbox;private final TransactionTemplate tx;
 private final tools.jackson.databind.ObjectMapper mapper=new tools.jackson.databind.ObjectMapper();
 private final java.time.Clock clock;
 @org.springframework.beans.factory.annotation.Autowired
 public JdbcExchangeDispatches(NamedParameterJdbcTemplate jdbc,ExchangeApplications applications,PhysicalOrders physical,ExchangeReservations reservations,PhysicalStocks stocks,ExchangeShipments shipments,ExchangeOffers offers,JdbcExchanges exchanges,Jobs jobs,JobLeases leases,Outbox outbox,PlatformTransactionManager manager) { this(jdbc,applications,physical,reservations,stocks,shipments,offers,exchanges,jobs,leases,outbox,manager,null); }
 public JdbcExchangeDispatches(NamedParameterJdbcTemplate jdbc,ExchangeApplications applications,PhysicalOrders physical,ExchangeReservations reservations,PhysicalStocks stocks,ExchangeShipments shipments,ExchangeOffers offers,JdbcExchanges exchanges,Jobs jobs,JobLeases leases,Outbox outbox,PlatformTransactionManager manager,java.time.Clock clock) { this.jdbc=jdbc;this.applications=applications;this.physical=physical;this.reservations=reservations;this.stocks=stocks;this.shipments=shipments;this.offers=offers;this.exchanges=exchanges;this.jobs=jobs;this.leases=leases;this.outbox=outbox;this.tx=new TransactionTemplate(manager); this.clock=clock; }
 @Override public Exchanges.Progress request(UUID id,OrderQueries.Authority authority,Exchanges.Command command) {
  if(command==null||command.key()==null||!command.key().matches("[A-Za-z0-9][A-Za-z0-9._:-]{0,99}")||command.expectedRevision()==null||command.expectedRevision()<0||command.reason()==null||command.reason().isBlank()||command.reason().length()>500) { throw new OrderRejected(400); }
  return tx.execute(t->{applications.lockSeller(authority,id);var row=exchanges.lock(id);String reason=command.reason().trim(),hash=hash("RESHIP|"+command.expectedRevision()+"|"+reason);var old=jdbc.queryForList("SELECT fingerprint,receipt::text FROM marketplace.claim_exchange_command WHERE exchange_id=:id AND command_key=:key",Map.of("id",id,"key",command.key()));
   if(!old.isEmpty()) { if(!hash.equals(old.getFirst().get("fingerprint"))) { throw new OrderRejected(409); }applications.lockSeller(authority,id);return mapper.readValue(old.getFirst().get("receipt").toString(),Exchanges.Progress.class); }
   var progress=exchanges.progress(id);var currentReservations=reservations.lockCurrent(id);if(!row.get("state").equals("READY")||((Number)row.get("version")).longValue()!=command.expectedRevision()||progress.physical().stream().anyMatch(p->!p.collection().equals("RECEIVED")||p.inspectionId()==null)||currentReservations.isEmpty()||currentReservations.stream().anyMatch(r->!r.status().equals("RESERVED"))) { throw new OrderRejected(409); }
   var at=now();if(!at.isBefore(((Timestamp)row.get("expires_at")).toInstant())) { throw new OrderRejected(409); }long version=Math.incrementExact(command.expectedRevision());UUID request=UUID.randomUUID();var p=new MapSqlParameterSource("id",id).addValue("request",request).addValue("version",version).addValue("key",command.key()).addValue("hash",hash).addValue("at",Timestamp.from(at));
   jdbc.update("UPDATE marketplace.claim_exchange_request SET state='DISPATCH_PENDING',version=:version WHERE id=:id",p);exchanges.history(id,"DISPATCH_PENDING",version,reason,authority,at);exchanges.event(id,((Number)row.get("current_sequence")).intValue()==1?"reship-requested":"reship-requested-"+row.get("current_sequence"),at);var result=exchanges.progress(id);jdbc.update("INSERT INTO marketplace.claim_exchange_command(exchange_id,command_key,fingerprint,action,version,receipt) VALUES(:id,:key,:hash,'DISPATCH_PENDING',:version,CAST(:receipt AS jsonb))",p.addValue("sequence",row.get("current_sequence")).addValue("receipt",mapper.writeValueAsString(result)));jdbc.update("INSERT INTO marketplace.claim_exchange_dispatch_request(id,exchange_id,sequence,version,command_key,requested_at) VALUES(:request,:id,:sequence,:version,:key,:at)",p);
   String key="exchange-reship:"+request;outbox.append(new Outbox.Event(UUID.nameUUIDFromBytes(key.getBytes(java.nio.charset.StandardCharsets.UTF_8)),new Jobs.Command(TYPE,key,id.toString(),id+"|"+request,at)));applications.lockSeller(authority,id);return result;
  });
 }
 private void owned(Jobs.Job job,UUID id,UUID request) {
  var actual=jobs.find(job.id()).orElseThrow(()->new OrderRejected(409));if(!actual.command().equals(job.command())||!actual.status().equals("RUNNING")||!java.util.Objects.equals(actual.ownerToken(),job.ownerToken())||!job.command().type().equals(TYPE)||!job.command().dedupeKey().equals("exchange-reship:"+request)||!job.command().causeKey().equals(id.toString())||!job.command().payload().equals(id+"|"+request)) { throw new OrderRejected(409); }
 }
 public JobHandler.Result dispatch(Jobs.Job job) {
  if(job==null||job.command()==null||job.id()==null||job.ownerToken()==null) { throw new OrderRejected(400); }UUID id,request;try { var parts=job.command().payload().split("\\|",-1);if(parts.length!=2) { throw new IllegalArgumentException(); }id=UUID.fromString(parts[0]);request=UUID.fromString(parts[1]); }catch(IllegalArgumentException invalid) { throw new OrderRejected(400); }
  return tx.execute(t->{owned(job,id,request);var converted=converted(job,id,request);if(converted!=null) { return converted; }var obsolete=superseded(job,id,request);if(obsolete!=null) { return obsolete; }if(jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_dispatch_effect WHERE exchange_id=:id",Map.of("id",id),Integer.class)==1) { return replay(job,id,request); }var hint=exchanges.source(id);var desired=exchanges.receipt(id).units().stream().map(Exchanges.Unit::targetSkuId).toList();var eligibility=offers.lockExistingTrade(hint.storeId(),desired);var app=applications.lockRecorded(id);var row=exchanges.lock(id);exchanges.requireTradeTargets(id,eligibility);var command=jdbc.queryForList("SELECT * FROM marketplace.claim_exchange_dispatch_request WHERE id=:request AND exchange_id=:id",Map.of("request",request,"id",id));if(command.size()!=1) { throw new OrderRejected(409); }
   if(jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_dispatch_effect WHERE exchange_id=:id",Map.of("id",id),Integer.class)==1) { return replay(job,id,request); }
   if(!row.get("state").equals("DISPATCH_PENDING")||((Number)row.get("version")).longValue()!=JdbcExchangeReservationCommands.dispatchRevision(jdbc,id,((Number)command.getFirst().get("version")).longValue())) { throw new OrderRejected(409); }
   var received=physical.application(id);var balances=new java.util.ArrayList<UUID>(desired);balances.addAll(received.stream().map(s->s.stock().skuId()).toList());stocks.lockBalances(balances);var progress=exchanges.progress(id);if(progress.physical().stream().anyMatch(p->!p.collection().equals("RECEIVED")||p.inspectionId()==null)) { throw new OrderRejected(409); }
   exchanges.requireTradeTargets(id,offers.lockExistingTrade(hint.storeId(),desired));var committed=reservations.commit(id,request);var sources=committed.stream().map(r->stocks.exchanged(r.id())).toList();var fact=shipments.dispatch(request,app,received,committed,sources);physical.dispatched(fact);long version=Math.incrementExact(((Number)row.get("version")).longValue());var at=now();var p=new MapSqlParameterSource("id",id).addValue("request",request).addValue("shipment",fact.shipmentId()).addValue("version",version).addValue("at",Timestamp.from(at)).addValue("job",job.id()).addValue("owner",job.ownerToken());
   jdbc.update("UPDATE marketplace.claim_exchange_request SET state='DISPATCHED',version=:version WHERE id=:id",p);jdbc.update("INSERT INTO marketplace.claim_exchange_history(id,exchange_id,action,version,reason,actor,occurred_at) VALUES(:event,:id,'DISPATCHED',:version,'ACTUAL_EXCHANGE_RESERVATION_COMMITTED','RECORDED_WORKER',:at)",p.addValue("event",UUID.randomUUID()));exchanges.event(id,"dispatched",at);jdbc.update("INSERT INTO marketplace.claim_exchange_dispatch_effect(exchange_id,dispatch_id,shipment_id,version,job_id,owner_token,recorded_at) VALUES(:id,:request,:shipment,:version,:job,:owner,:at)",p);owned(job,id,request);leases.requireOwned(job.id(),job.ownerToken());return JobHandler.Result.COMPLETE;
  });
 }
 private JobHandler.Result converted(Jobs.Job job,UUID id,UUID request) {
  var route=jdbc.queryForList("SELECT r.sequence,c.sequence AS converted_sequence FROM marketplace.claim_exchange_dispatch_request r JOIN marketplace.claim_exchange_refund_consent c ON c.exchange_id=r.exchange_id WHERE r.id=:request AND r.exchange_id=:id",Map.of("request",request,"id",id));if(route.isEmpty()) { return null; }if(route.size()!=1) { throw new OrderRejected(409); }
  applications.lockRecorded(id);var row=exchanges.lock(id);if(!java.util.List.of("REFUND_PENDING","REVIEW_REQUIRED","SETTLEMENT_PENDING","REFUNDED").contains(row.get("state").toString())||((Number)route.getFirst().get("sequence")).intValue()>((Number)route.getFirst().get("converted_sequence")).intValue()||jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_dispatch_effect WHERE exchange_id=:id",Map.of("id",id),Integer.class)!=0) { throw new OrderRejected(409); }
  int sequence=((Number)route.getFirst().get("sequence")).intValue();var released=reservations.released(id,sequence);var stock=reservations.get(id).stream().filter(r->r.sequence()==sequence).toList();if(stock.isEmpty()||stock.stream().anyMatch(r->!java.util.List.of("EXPIRED","RELEASED").contains(r.status()))||!java.util.List.of(ExchangeReservations.ReleaseReason.EXPIRED,ExchangeReservations.ReleaseReason.REFUND_CONVERSION).contains(released.reason())) { throw new OrderRejected(409); }
  try { jdbc.queryForList("SELECT marketplace.verify_exchange_refund_consent(:id)",Map.of("id",id)); }catch(org.springframework.dao.DataIntegrityViolationException invalid) { throw new OrderRejected(409); }owned(job,id,request);leases.requireOwned(job.id(),job.ownerToken());return JobHandler.Result.COMPLETE;
 }
 private JobHandler.Result superseded(Jobs.Job job,UUID id,UUID request) {
  var hints=jdbc.queryForList("SELECT r.sequence,c.current_sequence,c.state FROM marketplace.claim_exchange_dispatch_request r JOIN marketplace.claim_exchange_request c ON c.id=r.exchange_id WHERE r.id=:request AND r.exchange_id=:id",Map.of("request",request,"id",id));if(hints.size()!=1) { throw new OrderRejected(409); }var hint=hints.getFirst();int sequence=((Number)hint.get("sequence")).intValue();if(sequence==((Number)hint.get("current_sequence")).intValue()&&!java.util.List.of("EXPIRED","REVIEW_REQUIRED").contains(hint.get("state").toString())) { return null; }
  applications.lockRecorded(id);var row=exchanges.lock(id);int current=((Number)row.get("current_sequence")).intValue();if(sequence>current||sequence==current&&!java.util.List.of("EXPIRED","REVIEW_REQUIRED").contains(row.get("state").toString())) { return null; }
  var release=reservations.released(id,sequence);if(release.reason()!=ExchangeReservations.ReleaseReason.EXPIRED||jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_expiry_delivery WHERE exchange_id=:id AND sequence=:seq AND release_id=:release AND mode='EXPIRED'",Map.of("id",id,"seq",sequence,"release",release.id()),Integer.class)!=1||jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_dispatch_effect WHERE exchange_id=:id AND dispatch_id=:request",Map.of("id",id,"request",request),Integer.class)!=0) { throw new OrderRejected(409); }
  owned(job,id,request);leases.requireOwned(job.id(),job.ownerToken());return JobHandler.Result.COMPLETE;
 }
 private JobHandler.Result replay(Jobs.Job job,UUID id,UUID request) {
  var app=applications.lockRecorded(id);var row=exchanges.lock(id);var receipts=jdbc.queryForList("SELECT * FROM marketplace.claim_exchange_dispatch_effect WHERE exchange_id=:id",Map.of("id",id));if(receipts.size()!=1) { throw new OrderRejected(409); }var receipt=receipts.getFirst();var proof=shipments.recorded(id);var fact=proof.fact();var stock=reservations.get(id).stream().filter(r->proof.reservationIds().contains(r.id())).toList();var fixed=physical.application(id);
  if(!java.util.List.of("DISPATCHED","COMPLETED").contains(row.get("state").toString())||!request.equals(receipt.get("dispatch_id"))||!job.id().equals(receipt.get("job_id"))||!request.equals(proof.dispatchId())||!receipt.get("shipment_id").equals(fact.shipmentId())||!app.orderId().equals(fact.orderId())||!app.sellerOrderId().equals(fact.sellerOrderId())||!id.equals(fact.exchangeId())||fixed.size()!=fact.units().size()||stock.size()!=proof.reservationIds().size()||stock.stream().anyMatch(r->!r.status().equals("COMMITTED"))||!new java.util.HashSet<>(proof.reservationIds()).equals(stock.stream().map(ExchangeReservations.Reservation::id).collect(java.util.stream.Collectors.toSet()))||jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_history WHERE exchange_id=:id AND version=:version AND action='DISPATCHED' AND actor='RECORDED_WORKER' AND occurred_at=:at",Map.of("id",id,"version",receipt.get("version"),"at",receipt.get("recorded_at")),Integer.class)!=1) { throw new OrderRejected(409); }
  for(var successor:fact.units()) { var original=fixed.stream().filter(p->p.id().equals(successor.predecessorId())).findFirst().orElseThrow(()->new OrderRejected(409));var actual=physical.recorded(successor.id());if(!actual.predecessorId().equals(original.id())||actual.round()!=original.round()+1||!actual.stock().id().equals(successor.stockSourceId())||actual.stock().kind()!=PhysicalStocks.Kind.EXCHANGE||!proof.reservationIds().contains(actual.stock().reservationId())||!actual.itemId().equals(original.itemId())||actual.ordinal()!=original.ordinal()||!actual.orderId().equals(app.orderId())||!actual.sellerOrderId().equals(app.sellerOrderId())) { throw new OrderRejected(409); } }
  var command=jdbc.queryForList("SELECT version FROM marketplace.claim_exchange_dispatch_request WHERE id=:request AND exchange_id=:id",Map.of("request",request,"id",id),Long.class);if(command.size()!=1||Math.incrementExact(JdbcExchangeReservationCommands.dispatchRevision(jdbc,id,command.getFirst()))!=((Number)receipt.get("version")).longValue()) { throw new OrderRejected(409); }owned(job,id,request);leases.requireOwned(job.id(),job.ownerToken());return JobHandler.Result.COMPLETE;
 }
 private static String hash(String value) { try { return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8))); }catch(java.security.NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); } }
 /** Production keeps its single database clock source; controlled integration fixtures supply the same explicit clock across the full workflow. */
 private java.time.Instant now() { return clock==null?jdbc.queryForObject("SELECT clock_timestamp()",Map.of(),Timestamp.class).toInstant():clock.instant(); }
}
